WITH src AS (SELECT *, ROUND(duration_sec, 2) AS duration_sec_rounded FROM web_events WHERE session_id IN (2, 11, 16, 24)), event_month_summary AS (SELECT DATE_TRUNC('MONTH', event_time) AS event_month, ROUND((100 * SUM(CASE WHEN page = '/checkout' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_checkout, COUNT(duration_sec_rounded) AS duration_sec_rounded_count FROM src GROUP BY DATE_TRUNC('MONTH', event_time)) SELECT event_month, pct_checkout, duration_sec_rounded_count FROM event_month_summary WHERE pct_checkout >= 33 ORDER BY pct_checkout DESC
